<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{Access,Files,Audit,Records};
class GuestController {
 private function table(string $kind):string{abort_unless(in_array($kind,['tamu','sewa']),404);return $kind==='tamu'?'tamu_menginap':'sewa_penghuni';}
 private function query(string $kind){$q=DB::table($this->table($kind).' as g')->join('hunian as h','h.id','=','g.hunian_id')->join('rt as r','r.id','=','h.rt_id')->whereNull('g.deleted_at')->select('g.*','h.alamat','h.rt_id','r.nomor as rt_nomor');if(!auth()->user()->isAdmin())$q->whereIn('h.rt_id',Access::ids());if(auth()->user()->roleCode()==='WARGA')$q->where('g.pelapor_id',auth()->id());return $q;}
 private function write():void{abort_unless(auth()->user()->isOperator()||auth()->user()->roleCode()==='WARGA',403);}
 public function index(Request $r,string $kind){Access::menu($kind);$q=$this->query($kind);if($r->filled('q'))$q->where('g.nama','like','%'.mb_substr($r->string('q'),0,100).'%');return view('guests',['kind'=>$kind,'rows'=>$q->orderByDesc('g.id')->paginate(15)->withQueryString()]);}
 public function form(string $kind,?int $id=null){Access::menu($kind,$id?'ubah':'tambah');$this->write();$row=$id?$this->query($kind)->where('g.id',$id)->first():null;abort_if($id&&!$row,404);return view('guest-form',['kind'=>$kind,'row'=>$row,'options'=>Records::options()]);}
 public function save(Request $r,string $kind,?int $id=null){Access::menu($kind,$id?'ubah':'tambah');$this->write();$table=$this->table($kind);$old=$id?$this->query($kind)->where('g.id',$id)->first():null;abort_if($id&&!$old,404);$rules=['nama'=>'required|string|max:150','nik'=>'nullable|digits:16','hunian_id'=>'required|integer|exists:hunian,id','identitas'=>Files::rule()];$rules+=$kind==='tamu'?['alamat_asal'=>'required|string|max:2000','tujuan'=>'required|string|max:2000','mulai'=>'required|date','rencana_selesai'=>'required|date|after_or_equal:mulai']:['tanggal_masuk'=>'required|date','tanggal_selesai'=>'required|date|after_or_equal:tanggal_masuk','nama_kontak_darurat'=>'required|string|max:150','telepon_darurat'=>'required|string|max:25'];$v=$r->validate($rules);Access::hunian((int)$v['hunian_id']);abort_unless(!empty($v['nik'])||$r->hasFile('identitas')||$old?->identitas_berkas_id,422,'Isi NIK atau unggah foto identitas.');unset($v['identitas']);
  DB::transaction(function()use($r,$v,$id,$old,$table){if($r->hasFile('identitas'))$v['identitas_berkas_id']=Files::upload($r->file('identitas'));if($id){DB::table($table)->where('id',$id)->update($v+['updated_at'=>now()]);$new=$id;}else{$new=DB::table($table)->insertGetId($v+['pelapor_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);}Audit::record($id?'ubah':'tambah',$table,$new,$old,$v);});return redirect('/'.$kind)->with('success','Data masa tinggal tersimpan.');}
 public function end(string $kind,int $id){Access::menu($kind,'ubah');$this->write();$row=$this->query($kind)->where('g.id',$id)->first();abort_unless($row,404);$field=$kind==='tamu'?'selesai_aktual':'tanggal_keluar_aktual';DB::table($this->table($kind))->where('id',$id)->update([$field=>now(),'updated_at'=>now()]);Audit::record('akhiri_masa_tinggal',$this->table($kind),$id);return back()->with('success','Tanggal keluar telah dicatat.');}
 public function destroy(string $kind,int $id){abort_unless(auth()->user()->isAdmin(),403);$row=$this->query($kind)->where('g.id',$id)->first();abort_unless($row,404);DB::table($this->table($kind))->where('id',$id)->update(['deleted_at'=>now(),'updated_at'=>now()]);Audit::record('hapus_logis',$this->table($kind),$id,$row);return back()->with('success','Data dihapus dari daftar aktif.');}
}
